/* GENERATED by gen/routec_jni_gen.py — Route C step 3b JNI GL bridge. DEVICE-ONLY runtime; compile-
   checked for iOS arm64. Forwards the base `gpu` plugin's facade calls to GLES / RouteCBridge. */
#import <Foundation/Foundation.h>
#import <QuartzCore/QuartzCore.h>   // CACurrentMediaTime for the perf counter (STRIP with the rest of the diag)
#define GLES_SILENCE_DEPRECATION 1   // OpenGLES is deprecated-since-iOS-12 but works on iOS 26 (no Metal-GL bridge needed)
