// DEVICE-DIAGNOSTIC (temporary): append a one-shot trace line to Documents/routec-trace.log so we can pinpoint
// how far the gpu plugin's startUp gets through the bridge (loadNatives -> createGLContext -> createCapabilities
// -> first getFramebuffer -> first swapBuffers). Low-frequency one-shots only; open/append/close per call is fine.
// STRIP after the GPU device round is green.
static void rc_trace(NSString *msg)
{
    static NSString *path = nil;
    if (!path) {
        NSString *docs = NSSearchPathForDirectoriesInDomains(NSDocumentDirectory, NSUserDomainMask, YES).firstObject;
        path = [[docs stringByAppendingPathComponent:@"routec-trace.log"] copy];
        FILE *t = fopen(path.UTF8String, "w");  // truncate once per PROCESS so each launch's trace stands alone
        if (t) { fputs("==== GPU RUN START (one launch) ====\n", t); fclose(t); }
    }
    FILE *f = fopen(path.UTF8String, "a");
    if (f) { fprintf(f, "%s\n", msg.UTF8String); fclose(f); }
}

// WHITE-FLASH DIAGNOSTIC (one-shot): dump the GL state at the first scene draw so a wrong depth/blend/texture/
// program/writemask setup is visible. STRIP after the white-flash bug is fixed.
static void rc_dump_gl_state(const char *whenLabel)
{
    GLenum errBefore = glGetError();
    GLint prog = 0;       glGetIntegerv(GL_CURRENT_PROGRAM, &prog);
    GLint dfunc = 0;      glGetIntegerv(GL_DEPTH_FUNC, &dfunc);
    GLboolean dtest = glIsEnabled(GL_DEPTH_TEST);
    GLboolean dmask = 0;  glGetBooleanv(GL_DEPTH_WRITEMASK, &dmask);
    GLfloat drange[2] = {0,0}; glGetFloatv(GL_DEPTH_RANGE, drange);
    GLfloat dclear = 0;  glGetFloatv(GL_DEPTH_CLEAR_VALUE, &dclear);
    GLfloat cclear[4] = {0,0,0,0}; glGetFloatv(GL_COLOR_CLEAR_VALUE, cclear);
    GLboolean blend = glIsEnabled(GL_BLEND);
    GLint bsrc = 0, bdst = 0; glGetIntegerv(GL_BLEND_SRC_RGB, &bsrc); glGetIntegerv(GL_BLEND_DST_RGB, &bdst);
    GLboolean cull = glIsEnabled(GL_CULL_FACE);
    GLboolean cmask[4] = {0,0,0,0}; glGetBooleanv(GL_COLOR_WRITEMASK, cmask);
    GLint atex = 0; glGetIntegerv(GL_ACTIVE_TEXTURE, &atex);
    GLint texArr = 0; glGetIntegerv(GL_TEXTURE_BINDING_2D_ARRAY, &texArr);
    GLint fbo = 0; glGetIntegerv(GL_FRAMEBUFFER_BINDING, &fbo);
    GLint vp[4] = {0,0,0,0}; glGetIntegerv(GL_VIEWPORT, vp);
    // Depth-fix recon: does iOS GLES expose clip_control (exact desktop reverse-Z, full depth precision) or a
    // depth-clamp ext? If yes -> implement glClipControl for real; if no -> fix via a projection clip-z remap.
    const char *exts = (const char *)glGetString(GL_EXTENSIONS);
    BOOL hasClipControl = exts && (strstr(exts, "clip_control") != NULL);
    BOOL hasDepthClamp  = exts && (strstr(exts, "depth_clamp") != NULL);
    GLenum errAfter = glGetError();
    rc_trace([NSString stringWithFormat:@"[routec] EXT clip_control=%d depth_clamp=%d", hasClipControl, hasDepthClamp]);
    rc_trace([NSString stringWithFormat:
        @"[routec] GLSTATE @%s err(before=0x%x after=0x%x) prog=%d fbo=%d viewport=%d,%d,%d,%d\n"
        @"         depth[test=%d func=0x%x mask=%d range=%.3f..%.3f clear=%.3f]  color[clear=%.3f,%.3f,%.3f,%.3f writemask=%d%d%d%d]\n"
        @"         blend[on=%d src=0x%x dst=0x%x] cull=%d activeTex=0x%x texBinding2DArray=%d",
        whenLabel, errBefore, errAfter, prog, fbo, vp[0],vp[1],vp[2],vp[3],
        dtest, dfunc, dmask, drange[0], drange[1], dclear,
        cclear[0],cclear[1],cclear[2],cclear[3], cmask[0],cmask[1],cmask[2],cmask[3],
        blend, bsrc, bdst, cull, atex, texArr]);
}

// (*env)->NewDirectByteBuffer returns a ByteBuffer whose byte order defaults to BIG_ENDIAN (JNI/Java spec).
// But LWJGL hands the plugin mapped buffers in NATIVE order (little-endian on iOS arm64), and the plugin writes
// all vertex + interface-pixel data through buffer.asIntBuffer() (VBO.java:79, GpuPlugin.prepareInterfaceTexture)
// WITHOUT setting an order — so it assumes native. Left big-endian, every int/short is byte-swapped before the
// little-endian GPU reads it -> corrupt vertex positions/colors (huge stretched garbage triangles) + wrong
// interface texels. Reconfigure the returned buffer to native order: bb.order(ByteOrder.nativeOrder()).
static jobject rc_native_order(JNIEnv *env, jobject bb)
{
    if (!bb) return bb;
    jclass boCls = (*env)->FindClass(env, "java/nio/ByteOrder");
    jclass bbCls = (*env)->FindClass(env, "java/nio/ByteBuffer");
    if (boCls && bbCls) {
        jmethodID nativeOrder = (*env)->GetStaticMethodID(env, boCls, "nativeOrder", "()Ljava/nio/ByteOrder;");
        jmethodID order = (*env)->GetMethodID(env, bbCls, "order", "(Ljava/nio/ByteOrder;)Ljava/nio/ByteBuffer;");
        if (nativeOrder && order) {
            jobject no = (*env)->CallStaticObjectMethod(env, boCls, nativeOrder);
            jobject ret = (*env)->CallObjectMethod(env, bb, order, no); // returns `this`, reconfigured
            if (ret) bb = ret;
        }
    }
    (*env)->ExceptionClear(env);
    return bb;
}

static void rc_awt_create_context(JNIEnv *env)
{
    int w = 512, h = 512; /* default for the L1 probe (no engine canvas) */
    jclass jb = (*env)->FindClass(env, "net/runelite/client/headless/JavaBridge");
    if (jb) {
        jmethodID cw = (*env)->GetStaticMethodID(env, jb, "canvasWidth", "()I");
        jmethodID ch = (*env)->GetStaticMethodID(env, jb, "canvasHeight", "()I");
        if (cw && ch) {
            jint qw = (*env)->CallStaticIntMethod(env, jb, cw);
            jint qh = (*env)->CallStaticIntMethod(env, jb, ch);
            if (qw > 0 && qh > 0) { w = (int)qw; h = (int)qh; }
        }
    }
    (*env)->ExceptionClear(env); /* optional probe — ignore FindClass/NoSuchMethod (L1 has no JavaBridge) */
    [RouteCBridge awtCreateGLContextWidth:w height:h];
}

// Location of the scene program's "worldProj" uniform, sniffed from glGetUniformLocation, for the reverse-Z
// clip-z remap in glUniformMatrix4fv (iOS GLES has no glClipControl). -1 = not yet seen.
static GLint s_worldProjLoc = -1;

// Cached JavaBridge handles for the per-frame GPU publish (resolved once, lazily, after registration).
static jclass    s_jb  = NULL;
static jmethodID s_bb  = NULL;  // gpuFrameBackBuffer(II)[I
static jmethodID s_pub = NULL;  // gpuPublish(II)V
static jmethodID s_cw  = NULL;  // canvasWidth()I
static jmethodID s_ch  = NULL;  // canvasHeight()I
static void rc_jb_cache(JNIEnv *env)
{
    if (s_jb) return;
    jclass c = (*env)->FindClass(env, "net/runelite/client/headless/JavaBridge");
    if (!c) { (*env)->ExceptionClear(env); return; }
    s_jb  = (*env)->NewGlobalRef(env, c);
    s_bb  = (*env)->GetStaticMethodID(env, s_jb, "gpuFrameBackBuffer", "(II)[I");
    s_pub = (*env)->GetStaticMethodID(env, s_jb, "gpuPublish", "(II)V");
    s_cw  = (*env)->GetStaticMethodID(env, s_jb, "canvasWidth", "()I");
    s_ch  = (*env)->GetStaticMethodID(env, s_jb, "canvasHeight", "()I");
    (*env)->ExceptionClear(env);
}

// Per-frame upkeep (called from getFramebuffer, early in each draw): re-bind the thread-affine EAGL context and
// recreate the FBO if the engine canvas resized. setCurrentContext is a no-op on the same thread (the expected
// case) but removes the off-thread-draw risk entirely.
static void rc_per_frame(JNIEnv *env)
{
    [RouteCBridge makeCurrent];
    rc_jb_cache(env);
    if (s_cw && s_ch) {
        jint w = (*env)->CallStaticIntMethod(env, s_jb, s_cw);
        jint h = (*env)->CallStaticIntMethod(env, s_jb, s_ch);
        if (w > 0 && h > 0) [RouteCBridge ensureSizeWidth:(int)w height:(int)h];
    }
}

// swapBuffers: read the composited FBO back and publish it as the SOLE frame (Hooks gates the CPU snapshot off
// when isGpu). glReadPixels straight into the JavaBridge back buffer via GetPrimitiveArrayCritical — no JNI calls
// inside the critical section (glReadPixels is a GL call; the flip/swizzle is pure C).
static void rc_swap_publish(JNIEnv *env)
{
    [RouteCBridge makeCurrent];
    int w = [RouteCBridge fbWidth], h = [RouteCBridge fbHeight];
    if (w <= 0 || h <= 0) return;
    rc_jb_cache(env);
    if (!s_bb || !s_pub) return;
    jintArray arr = (jintArray)(*env)->CallStaticObjectMethod(env, s_jb, s_bb, (jint)w, (jint)h);
    if (!arr) return;
    // PERF SPLIT (temporary): time the GPU render wait (glFinish) SEPARATELY from the readback copy. glReadPixels
    // implicitly waits for the GPU, so the old "readback" number conflated GPU-render-time + copy-time. Splitting
    // them decides the CAEAGLLayer question: if gpuFinish dominates -> GPU-bound (direct present caps near 1/gpuMs,
    // also need to cut GPU load); if copy dominates -> direct present (no readback) is the big win.
    double tGpu = 0, tCopy = 0;
    double g0 = CACurrentMediaTime();
    glFinish();                              // block until the GPU has finished rendering THIS frame
    tGpu = CACurrentMediaTime() - g0;        // = GPU render time/frame
    void *dst = (*env)->GetPrimitiveArrayCritical(env, arr, NULL);
    if (dst) {
        double r0 = CACurrentMediaTime();
        [RouteCBridge readbackInto:(uint32_t *)dst width:w height:h];  // GPU already done -> pure CPU copy+flip
        tCopy = CACurrentMediaTime() - r0;
        (*env)->ReleasePrimitiveArrayCritical(env, arr, dst, 0);
    }
    (*env)->CallStaticVoidMethod(env, s_jb, s_pub, (jint)w, (jint)h);
    (*env)->DeleteLocalRef(env, arr);

    // PERF (temporary, STRIP after tuning): engine composite FPS + the GPU-vs-copy split. One line/sec.
    static int frames = 0; static double accGpu = 0, accCopy = 0, lastLog = 0;
    double now = CACurrentMediaTime();
    frames++; accGpu += tGpu; accCopy += tCopy;
    if (lastLog == 0) lastLog = now;
    double span = now - lastLog;
    if (span >= 1.0) {
        rc_trace([NSString stringWithFormat:@"[perf] engine=%.1f fps  gpuFinish=%.2f ms  copy=%.2f ms  (%d frames, %dx%d)",
            frames / span, (accGpu / frames) * 1000.0, (accCopy / frames) * 1000.0, frames, w, h]);
        frames = 0; accGpu = 0; accCopy = 0; lastLog = now;
    }
}

